/bin/bash -lc "python - <<'PY'
import requests
for repo in ['r-base','r-base64','r']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/'
    try:
        r=requests.get(url, params={'limit':10}, timeout=20)
        print(repo, r.status_code)
        if r.ok:
            tags=[t['name'] for t in r.json().get('tags', [])[:10]]
            print('\\n'.join(tags[:5]))
    except Exception as e:
        print(repo, type(e).__name__, e)
PY"

